/* @lc app=leetcode id=3488 lang=kotlin */ class Solution { fun solveQueries(nums: IntArray, queries: IntArray): List<Int> = nums.indices.groupBy { nums[it] }.let { g -> queries.map { q -> g[nums[q]]!!.let { ps -> if (ps.size == 1) -1 else ps.binarySearch(q).let { idx -> listOf(ps[(idx + 1) % ps.size], ps[(idx - 1 + ps.size) % ps.size]).minOf { p -> Math.abs(q - p).let { d -> minOf(d, nums.size - d) } } } } } } }